  st=u32(im(st,ka)+x);st=u32(im(rol16(st),0xCF98B111));st=u32(im(rol16(st),0x87085B9F));st=u32(im(rol16(st),0x12CEB96D));st=u32(im(rol16(st),0x257E1D83));acc=u32(acc+st);
