const WSS_BASE='https://speech.platform.bing.com/consumer/speech/synthesize/readaloud/edge/v1';
const UA=`Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/${CHROMIUM_MAJOR}.0.0.0 Safari/537.36 Edg/${CHROMIUM_MAJOR}.0.0.0`;
const VOICES=['km-KH-PisethNeural','km-KH-SreymomNeural'];
let clockSkew=0;
const rid=()=>crypto.randomUUID().replace(/-/g,'');
const muid=()=>[...crypto.getRandomValues(new Uint8Array(16))].map(b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();
const dateStr=()=>new Date().toUTCString().replace(/^(\w+), (\d+) (\w+) (\d+) ([\d:]+) GMT$/,(m,d,dd,mo,y,t)=>`${d} ${mo} ${dd} ${y} ${t} GMT+0000 (Coordinated Universal Time)`);
const xmlEsc=t=>t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const clean=t=>String(t||'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,' ').trim();
const sign=(v,u)=>{v=Math.round(Number(v)||0);return(v>=0?'+':'')+v+u};
const fullVoice=v=>{const m=/^([a-z]{2,})-([A-Z]{2,})-(.+Neural)$/.exec(v);return m?`Microsoft Server Speech Text to Speech Voice (${m[1]}-${m[2]}, ${m[3]})`:v};
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'GET, POST, OPTIONS'};
const json=(o,status=200)=>new Response(JSON.stringify(o),{status,headers:{...cors,'Content-Type':'application/json; charset=utf-8'}});

async function edgeTTS(text,voice,rate,pitch,wssBase=WSS_BASE,retry=true){
  text=xmlEsc(clean(text)).slice(0,3000);if(!text)throw new Error('empty text');
  if(!VOICES.includes(voice)&&!/^[a-z]{2,}-[A-Z]{2,}-\w+Neural$/.test(voice))voice=VOICES[0];
  const url=`${wssBase}?TrustedClientToken=${TRUSTED_CLIENT_TOKEN}&ConnectionId=${rid()}&Sec-MS-GEC=${secMsGec(Date.now()/1000+clockSkew)}&Sec-MS-GEC-Version=${SEC_MS_GEC_VERSION}`;
  const resp=await fetch(url,{headers:{Upgrade:'websocket','Pragma':'no-cache','Cache-Control':'no-cache','Origin':'chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold','Sec-WebSocket-Version':'13','User-Agent':UA,'Accept-Encoding':'gzip, deflate, br, zstd','Accept-Language':'en-US,en;q=0.9','Cookie':`muid=${muid()};`}});
  const ws=resp.webSocket;
  if(!ws){if(resp.status===403&&retry){const d=Date.parse(resp.headers.get('Date')||'');if(d){clockSkew+=d/1000-Date.now()/1000;return edgeTTS(text,voice,rate,pitch,wssBase,false)}}throw new Error('Microsoft refused: HTTP '+resp.status)}
  ws.accept();
  return await new Promise((resolve,reject)=>{const chunks=[];let finished=false;
    const done=(err)=>{if(finished)return;finished=true;clearTimeout(timer);try{ws.close(1000)}catch(e){}
      if(err&&!chunks.length)return reject(err);if(!chunks.length)return reject(new Error('no audio received'));
      const n=chunks.reduce((a,c)=>a+c.length,0),out=new Uint8Array(n);let o=0;for(const c of chunks){out.set(c,o);o+=c.length}resolve(out)};
    const timer=setTimeout(()=>done(new Error('timeout')),30000);
    ws.addEventListener('message',ev=>{const d=ev.data;
      if(typeof d==='string'){if(d.includes('Path:turn.end'))done()}
      else{const b=new Uint8Array(d);if(b.length<2)return;const hl=(b[0]<<8)|b[1];const head=new TextDecoder().decode(b.subarray(2,2+hl));if(head.includes('Path:audio')&&b.length>2+hl)chunks.push(b.slice(2+hl))}});
    ws.addEventListener('close',()=>done(new Error('connection closed')));
    ws.addEventListener('error',()=>done(new Error('websocket error')));
    ws.send(`X-Timestamp:${dateStr()}\r\nContent-Type:application/json; charset=utf-8\r\nPath:speech.config\r\n\r\n{"context":{"synthesis":{"audio":{"metadataoptions":{"sentenceBoundaryEnabled":"true","wordBoundaryEnabled":"false"},"outputFormat":"audio-24khz-48kbitrate-mono-mp3"}}}}\r\n`);
    ws.send(`X-RequestId:${rid()}\r\nContent-Type:application/ssml+xml\r\nX-Timestamp:${dateStr()}Z\r\nPath:ssml\r\n\r\n<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='en-US'><voice name='${fullVoice(voice)}'><prosody pitch='${sign(pitch,'Hz')}' rate='${sign(rate,'%')}' volume='+0%'>${text}</prosody></voice></speak>`);
  })}


